using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
public static class CompactTests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,(Action)(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 public static void Shot(CompactWindow window,string path){window.UpdateLayout();var element=(FrameworkElement)window.Content;int w=(int)Math.Ceiling(element.ActualWidth*1.25),h=(int)Math.Ceiling(element.ActualHeight*1.25);var image=new RenderTargetBitmap(w,h,120,120,PixelFormats.Pbgra32);image.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(path))encoder.Save(f);}
 static void LayoutCheck(CompactWindow mini){var root=mini.Surface;Check(root.ActualWidth>=280,"compact content width");foreach(var t in Texts(root)){if(string.IsNullOrEmpty(t.Text))continue;var rect=t.TransformToAncestor(root).TransformBounds(new Rect(0,0,t.ActualWidth,t.ActualHeight));Check(rect.Left>=-1&&rect.Right<=root.ActualWidth+1,"compact label horizontal bounds: "+t.Text);}}
 static IEnumerable<TextBlock> Texts(DependencyObject root){for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var c=VisualTreeHelper.GetChild(root,i);if(c is TextBlock)yield return (TextBlock)c;foreach(var t in Texts(c))yield return t;}}
 public static int Run(string folder){Directory.CreateDirectory(folder);Storage.PathName=Path.Combine(folder,"settings.xml");var host=new MonitorWindow(true){ShowActivated=false,ShowInTaskbar=false,Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual};host.CompactOptions.MiniLeft=-18000;host.CompactOptions.MiniTop=-18000;host.SetMetrics(Program.Fixture("eight"));int samples=host.History.Count;host.ShowCompact();var mini=host.CompactView;mini.Left=-18000;mini.Top=-18000;Pump();Check(!host.IsVisible&&mini.IsVisible&&mini.Topmost,"compact shown and topmost, main hidden");Check(host.History.Count==samples&&mini.GpuCount==8,"same capture data, no fabricated samples");mini.TogglePin();Check(!mini.Topmost&&!host.CompactOptions.MiniPinned,"unpin");mini.TogglePin();Check(mini.Topmost,"repin");int builds=mini.RowBuilds;host.SetMetrics(Program.Fixture("eight"),false);Check(mini.RowBuilds==builds,"poll retains GPU rows");var log=new List<string>{"SINGLE_EXISTING_COLLECTOR_AND_NO_FABRICATED_SAMPLES=True","SHOW_HIDE_TOPMOST_AND_PIN_TOGGLE=True","GPU_ROWS_RETAINED_ON_POLL=True"};
 int images=0;foreach(string theme in Theme.Keys){host.ApplyAppearance(theme);foreach(string fixture in new[]{"eight","two","none"})foreach(int width in new[]{320,360,480}){host.SetMetrics(Program.Fixture(fixture),false);mini.Width=width;mini.Height=480;Pump();mini.UpdateLayout();LayoutCheck(mini);Check(mini.GpuCount==host.CompactMetrics.Gpus.Count,"GPU topology "+fixture);Shot(mini,Path.Combine(folder,theme+"-"+fixture+"-"+width+".png"));images++;}}
 string previousCpu=mini.CpuText,previousMemory=mini.MemoryText;host.SetMetrics(new Metrics{Error="test disconnect"},false);Check(mini.CpuText==previousCpu&&mini.MemoryText==previousMemory&&mini.StateText.Contains("异常"),"disconnect preserves last valid values with explicit failure status");var local=Storage.LocalServer();host.ChooseServer(local);host.SetMetrics(Program.Fixture("none"),false);Check(mini.DevicePicker.SelectedItem is Server&&ArchiveStore.Key((Server)mini.DevicePicker.SelectedItem)==ArchiveStore.Key(local)&&mini.HasGpuMessage,"device switch and CPU only");var remote=host.CompactDevices.First(x=>!x.IsLocal);mini.DevicePicker.SelectedItem=remote;Check(host.CompactSelected==remote,"compact picker selects main device");host.SetMetrics(Program.Fixture("eight"),false);host.Restore();Check(host.IsVisible&&!mini.IsVisible,"expand returns to main");host.ShowCompact();mini.Close();Check(!host.IsVisible&&!mini.IsVisible,"close compact hides to tray");host.CompactOptions.MiniLeft=50;host.CompactOptions.MiniTop=70;var copy=host.CompactOptions.Copy();Check(copy.MiniPinned==host.CompactOptions.MiniPinned&&copy.MiniLeft==50,"settings copy preserves compact prefs");Storage.Save(copy);var loaded=Storage.Load();Check(loaded.MiniLeft==50&&loaded.MiniTop==70&&loaded.MiniWidth==mini.Width,"geometry persistence");log.Add("FOUR_THEMES_GPU_0_2_8_AND_WIDTH_320_360_480_RENDERS="+images);log.Add("DISCONNECT_CPU_ONLY_AND_BIDIRECTIONAL_DEVICE_SWITCH=True");log.Add("EXPAND_CLOSE_TO_TRAY_AND_GEOMETRY_PERSISTENCE=True");host.Exit();Theme.Apply("forest");File.WriteAllLines(Path.Combine(folder,"compact-results.txt"),log);return 0;}
}
